#include "CutAccuracy/Traversal.hpp"
#include <algorithm>
#include <cmath>
namespace CutAccuracy { namespace { struct D{double s{0},r{0},c{1e9};bool v{false};}; D m(const SaberPlaneSample&a,const OrientedBox&b){Vec3 n=normalized(a.normal);if(lengthSq(n)<1e-12)return{};double s=dot(n,b.center-a.point),r=std::abs(dot(n,normalized(b.axisX)))*b.halfExtent.x+std::abs(dot(n,normalized(b.axisY)))*b.halfExtent.y+std::abs(dot(n,normalized(b.axisZ)))*b.halfExtent.z;return{s,r,std::abs(s)-r,true};} double crossT(double t0,double g0,double t1,double g1){double den=g0-g1;if(std::abs(den)<1e-12)return(t0+t1)*.5;double u=std::clamp(g0/den,0.0,1.0);return t0+(t1-t0)*u;} std::optional<double> sparse(const std::vector<SaberPlaneSample>&s,const std::vector<D>&d,double cut,double eps){std::optional<double>best;double bd=1e99;for(size_t i=1;i<s.size();++i){auto&a=d[i-1];auto&b=d[i];if(!a.v||!b.v)continue;double h0=a.s-a.r,h1=b.s-b.r,l0=a.s+a.r,l1=b.s+b.r;bool pn=h0>=0&&l1<=0&&a.s>=b.s,np=l0<=0&&h1>=0&&a.s<=b.s;if(!pn&&!np)continue;double x=crossT(s[i-1].timeSeconds,h0,s[i].timeSeconds,h1),y=crossT(s[i-1].timeSeconds,l0,s[i].timeSeconds,l1),en=std::min(x,y),ex=std::max(x,y),dur=ex-en;if(dur<=eps)continue;double cd=cut<en?en-cut:cut>ex?cut-ex:0;if(cd<bd){bd=cd;best=dur;}}return best;} }
double planeBoxClearance(const SaberPlaneSample&s,const OrientedBox&b){return m(s,b).c;} std::optional<double> traversalTimeSeconds(const std::vector<SaberPlaneSample>&in,const OrientedBox&b,double cut,double eps){if(in.size()<2)return std::nullopt;auto s=in;std::sort(s.begin(),s.end(),[](auto&a,auto&b){return a.timeSeconds<b.timeSeconds;});std::vector<D>d(s.size());std::vector<double>g(s.size());for(size_t i=0;i<s.size();++i){d[i]=m(s[i],b);g[i]=d[i].c;}std::optional<size_t>a;double best=1e99;for(size_t i=0;i<s.size();++i)if(g[i]<=0){double dt=std::abs(s[i].timeSeconds-cut);if(dt<best){best=dt;a=i;}}if(a){size_t f=*a,l=*a;while(f>0&&g[f-1]<=0)--f;while(l+1<s.size()&&g[l+1]<=0)++l;if(f>0&&l+1<s.size()&&g[f-1]>0&&g[l+1]>0){double en=crossT(s[f-1].timeSeconds,g[f-1],s[f].timeSeconds,g[f]),ex=crossT(s[l].timeSeconds,g[l],s[l+1].timeSeconds,g[l+1]),dt=ex-en;if(dt>eps)return dt;}}return sparse(s,d,cut,eps);} }
